def countGoodStrings(n):
    MOD = 10**9 + 7

    # fast doubling: returns (F(k), F(k+1)) modulo MOD
    def fib(k):
        if k == 0:
            return (0, 1)
        a, b = fib(k >> 1)                  # a = F(m), b = F(m+1) with m = k // 2
        c = a * ((2 * b - a) % MOD) % MOD   # F(2m)   = F(m) * (2F(m+1) - F(m))
        d = (a * a + b * b) % MOD           # F(2m+1) = F(m)^2 + F(m+1)^2
        if k & 1:
            return (d, (c + d) % MOD)       # k odd: (F(2m+1), F(2m+2))
        return (c, d)                       # k even: (F(2m), F(2m+1))

    # good strings = (compositions of n into odd parts) x (2 choices for the first letter)
    return 2 * fib(n)[0] % MOD
